"""HTTP configuration for Mooship's two-server nginx project template (Python 3.8+)."""

import argparse
from pathlib import Path
import re
import sys
from typing import List, Tuple


def server_blocks(lines: List[str]) -> List[Tuple[int, int, List[str], bool]]:
    """Read the active or fully commented server blocks generated by Mooship."""
    blocks = []
    start = 0
    while start < len(lines):
        match = re.match(r"^\s*(#?)\s*server\s*\{\s*$", lines[start])
        if not match:
            start += 1
            continue
        commented = bool(match.group(1))
        body = []
        depth = 0
        for end in range(start, len(lines)):
            line = lines[end]
            if commented:
                if not line.startswith("#"):
                    raise ValueError("Expected a fully commented nginx server block")
                line = line[1:]
            body.append(line)
            code = line.split("#", 1)[0]
            depth += code.count("{") - code.count("}")
            if depth == 0:
                blocks.append((start, end + 1, body, commented))
                start = end + 1
                break
        else:
            raise ValueError("Unterminated nginx server block")
    return blocks


def http_configuration(content: str) -> str:
    lines = content.splitlines()
    blocks = server_blocks(lines)
    http = [block for block in blocks
            if any(re.match(r"^\s*listen\s+80\s*;", line) for line in block[2])]
    tls = [block for block in blocks
           if any(re.match(r"^\s*listen\s+443\s+ssl\s*;", line) for line in block[2])]
    if len(http) != 1 or len(tls) != 1:
        raise ValueError("Expected one HTTP and one HTTPS server in the Mooship template")

    # Reuse all application routes, PHP settings, document root, and Basic Auth.
    # Only TLS directives and HSTS are inappropriate for the HTTP listener.
    application = []
    for line in tls[0][2]:
        if re.match(r"^\s*(ssl_\w+\s|add_header\s+Strict-Transport-Security\s)", line):
            continue
        application.append(re.sub(r"(\blisten\s+)443\s+ssl\s*;", r"\g<1>80;", line))

    replacements = {
        http[0][0]: (http[0][1], application),
        tls[0][0]: (tls[0][1], ["#" + line for line in tls[0][2]]),
    }
    for start in sorted(replacements, reverse=True):
        end, replacement = replacements[start]
        lines[start:end] = replacement
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("configuration", type=Path)
    args = parser.parse_args()
    try:
        content = args.configuration.read_text(encoding="utf-8")
        result = http_configuration(content)
        args.configuration.write_text(result, encoding="utf-8")
    except (OSError, ValueError) as error:
        print("Mooship: {}".format(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
